//! Closed CQ27: original preparation, paid grave return and intrinsic movement prohibition.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use std::collections::BTreeSet;
pub(crate) const ID:&str="CQ27";
pub(crate) const PREPARE:&str="cq27-prepare-bottom-walker";
pub(crate) const GRAVE:&str="cq27-grave-return";
const TITLE:&str="骨根灵主：将自己墓地一张角色牌置于牌库底";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn immobile(c:&Card)->bool{c.definition==ID&&!c.face_down}
pub(crate) fn definition()->Definition{
 let mut grave=ability(GRAVE,"墓地行动：牺牲三个自己操控的角色，混乱回场",Timing::Standard,vec![Cost::CQ27SacrificeThree],vec![],vec![Op::CQ27GraveReturn],None);grave.activation_only=true;
 let mut d=with_abilities(vec![ability(PREPARE,TITLE,Timing::Fast,vec![],vec![],vec![Op::CQ27Prepare{event_id:None}],Some(Event::Prepare)),grave]);d.traits.chaos=true;d
}
fn owns(o:&Op)->bool{match o{Op::CQ27Prepare{..}|Op::CQ27GraveReturn=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("cq27-")||a.costs.iter().any(|c|matches!(c,Cost::CQ27SacrificeThree))||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID{return Err("骨根灵主程序不可移植".into());}if a.key==PREPARE{return crate::jc035::validate_ability(id,a);}if !same(a,&definition().abilities[1]){return Err("骨根灵主墓地行动须保留完整定义".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if (id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("骨根灵主完整定义不可改写或移植".into());}Ok(())}
fn frame_related(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("cq27-")||f.steps.iter().any(|s|owns(&s.op))||f.already_paid.iter().any(|p|matches!(p,PaidCost::CQ27Sacrificed(_)))}
pub(crate) fn validate_action(id:&str,a:&Action)->RuleResult<()>{if id!=ID{return Ok(());}let expected=match a.kind.as_str(){"asset"|"reveal"|"deploy"=>Action{card_id:a.card_id.clone(),..Action::new(&a.kind)},"conceal"=>Action{card_id:a.card_id.clone(),region:a.region,..Action::new("conceal")},_=>return Err("骨根灵主额外行动载荷无效".into())};if *a!=expected{return Err("骨根灵主混乱进场不得预指定地区或夹带载荷".into());}Ok(())}
impl Game{
 fn cq27_victims(&self,actor:usize)->Vec<SourceSnapshot>{self.in_play_cards().into_iter().filter_map(|(r,c)|{let r=r?;if c.controller!=actor||c.face_down||catalog::card(&c.definition).kind!="character"||!self.region_live(r){return None;}let mut s=self.source_snapshot(c,Some(r));s.source_region_instance=Some(self.regions[r].card.id.clone());Some(s)}).collect()}
 pub(crate) fn cq27_actions(&self,actor:usize)->Vec<(Action,String)>{let victims=self.cq27_victims(actor);let mut out=vec![];for c in self.players[actor].graveyard.iter().filter(|c|c.definition==ID){for i in 0..victims.len(){for j in i+1..victims.len(){for k in j+1..victims.len(){out.push((Action{card_id:Some(c.id.clone()),ability_id:Some(GRAVE.into()),cost_selected:Some(vec![victims[i].card.id.clone(),victims[j].card.id.clone(),victims[k].card.id.clone()]),..Action::new("activate")},"骨根灵主：牺牲三个角色，混乱回场".into()));}}}}out}
 pub(crate) fn cq27_begin(&mut self,actor:usize,a:&Action)->RuleResult<()>{if *a!=(Action{card_id:a.card_id.clone(),ability_id:Some(GRAVE.into()),cost_selected:a.cost_selected.clone(),..Action::new("activate")}){return Err("骨根灵主只接受原墓地来源与三角色费用".into());}let c=self.players[actor].graveyard.iter().find(|c|Some(&c.id)==a.card_id.as_ref()&&c.definition==ID).ok_or("骨根灵主必须在本人墓地")?;let source=self.source_snapshot(c,None);let spec=definition().abilities.remove(1);self.check_timing(actor,&spec)?;let paid=self.pay_ability_costs(actor,&source,&spec,a)?;let f=self.make_frame(actor,source,&spec,vec![],paid,None);self.dispatch_frame(f,spec.label,None,spec.response_policy);Ok(())}
 pub(crate) fn cq27_pay(&mut self,actor:usize,s:&SourceSnapshot,a:&Action)->RuleResult<PaidCost>{if s.card.definition!=ID||s.card.owner!=actor||s.card.controller!=actor||!self.players[actor].graveyard.iter().any(|c|same(c,&s.card)){return Err("骨根灵主原墓地身份失效".into());}let ids=a.cost_selected.as_ref().filter(|ids|ids.len()==3&&ids.iter().collect::<BTreeSet<_>>().len()==3).ok_or("须牺牲三个不同角色")?;let eligible=self.cq27_victims(actor);let mut victims=vec![];for id in ids{victims.push(eligible.iter().find(|s|&s.card.id==id).ok_or("牺牲对象不是自己操控的明置角色")?.clone());}let wave=victims.iter().map(|s|(s.card.id.clone(),RemovalCause::Sacrifice,s.clone())).collect();self.destroy_wave_as(actor,wave);Ok(PaidCost::CQ27Sacrificed(victims))}
 pub(crate) fn validate_cq27_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(());}if f.ability_key==PREPARE{if f.source.card.definition!=ID{return Err("骨根准备不能移植".into());}return self.validate_jc035_frame(f);}if matches!(f.ability_key.as_str(),"deploy"|"reveal"){return self.cq27_play_frame(f);}if self.validated_mobility_frame(f)?{return Ok(());}let s=&f.source;let c=&s.card;let [PaidCost::CQ27Sacrificed(v)]=f.already_paid.as_slice()else{return Err("缺少三角色真实牺牲回执".into());};
 if c.definition!=ID||f.ability_key!=GRAVE||f.actor>=self.players.len()||c.owner!=f.actor||c.controller!=f.actor||c.face_down||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||!f.targets.is_empty()||f.chosen_region.is_some()||!f.resource_payments.is_empty()||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!same(&f.steps,&vec![Step{context:f.actor,op:Op::CQ27GraveReturn}])||v.len()!=3||v.iter().map(|s|&s.card.id).collect::<BTreeSet<_>>().len()!=3{return Err("骨根灵主原墓地程序或费用身份损坏".into());}
 for s in v{let c=&s.card;if c.controller!=f.actor||c.owner>=self.players.len()||c.face_down||catalog::card(&c.definition).kind!="character"||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||self.batch3_physical_cards().any(|now|now.id==c.id){return Err("三角色牺牲回执不能重复或保留原实体".into());}self.validate_generated_identity(c)?;self.mobility_immutable_identity(c)?;}self.mobility_immutable_identity(c)
 }
 pub(crate) fn cq27_return(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_cq27_frame(f)?;if f.cursor!=1{return Err("骨根墓地行动未执行原守卫".into());}let Some(i)=self.players[f.actor].graveyard.iter().position(|c|same(c,&f.source.card))else{return Ok(());};let Some(r)=self.chaos_region()else{return Ok(());};let c=&self.players[f.actor].graveyard[i];if self.jc064_blocks_character(c,r){return Ok(());}let c=self.players[f.actor].graveyard.remove(i);let c=self.reset_zone_card(c);let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers_with_extra(f.actor,ID,&id,false,None,None,true);Ok(())}
 fn cq27_options(&self,f:&ResolutionFrame)->Vec<ChoiceOption>{self.players[f.actor].graveyard.iter().filter(|c|catalog::card(&c.definition).kind=="character").map(|c|self.option(c,f.actor,None,None)).collect()}
 fn cq27_generate(&mut self,f:&ResolutionFrame)->RuleResult<()>{if !self.players[f.actor].eliminated{if let Some(r)=self.original_region(&f.source){let c=self.make_generated(crate::generated::GeneratedKind::Walker,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,"TK001",&id,false);}}Ok(())}
 pub(crate) fn cq27_prepare(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_cq27_frame(f)?;let options=self.cq27_options(f);if options.is_empty(){return self.cq27_generate(f);}self.choice(f.actor,"cq27-bottom",TITLE.into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f.clone()),choice:FrameChoice::CQ27Bottom});Ok(())}
 pub(crate) fn cq27_bottom(&mut self,f:&ResolutionFrame,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.validate_cq27_frame(f)?;if f.cursor!=1||seat!=f.actor||ids.len()!=1||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")})||!self.cq27_options(f).iter().any(|o|o.id==ids[0]){return Err("骨根准备须选择自己墓地一张角色".into());}let i=self.players[seat].graveyard.iter().position(|c|c.id==ids[0]).unwrap();let c=self.players[seat].graveyard.remove(i);let c=self.reset_zone_card(c);self.players[seat].deck.push(c);self.cq27_generate(f)}
 pub(crate) fn validate_cq27_pending(&self,p:&Pending,f:&ResolutionFrame)->RuleResult<()>{self.validate_cq27_frame(f)?;let expected=Choice{id:p.choice.id.clone(),kind:"cq27-bottom".into(),title:TITLE.into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(f.actor),options:self.cq27_options(f),preview_cards:vec![],min:Some(1),max:Some(1),amount:None,allow_decline:Some(false)};if f.source.card.definition!=ID||f.ability_key!=PREPARE||f.cursor!=1||p.seat!=f.actor||!self.mystic_instance_valid(&p.choice.id)||expected.options.is_empty()||!same(&p.choice,&expected){return Err("骨根准备原待选损坏".into());}Ok(())}
 fn cq27_play_frame(&self,f:&ResolutionFrame)->RuleResult<()>{self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;let reveal=f.ability_key=="reveal";
 if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.chosen_region!=s.region||if reveal{!c.face_down||s.play_source.is_some()||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))}else{f.ability_key!="deploy"||c.face_down||!s.valid_character_play()||s.region.is_some()||s.source_region_instance.is_some()}||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=5&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|self.mystic_instance_valid(id)&&id!=&c.id)){return Err("骨根灵主原派遣/现身事务损坏".into());}self.mobility_immutable_identity(c)
 }
 pub(crate) fn validate_cq27_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){let f=i.frame.as_ref().ok_or("骨根灵主实际角色事务缺帧")?;self.cq27_play_frame(f)?;if i.id!=f.frame_id||i.controller!=f.actor||i.target.is_some()||i.reveal!=(f.ability_key=="reveal")||i.deploy_region!=f.source.region||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("骨根实际事务与原帧不符".into());}}Ok(())}
 pub(crate) fn validate_cq27_state(&self)->RuleResult<()>{let mut ids=BTreeSet::new();for i in &self.stack{self.validate_cq27_play(i)?;if let Some(f)=&i.frame{self.validate_cq27_frame(f)?;if frame_related(f){if !ids.insert(&f.frame_id){return Err("骨根同帧重复".into());}if f.ability_key==GRAVE&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.is_some()||f.cursor!=0){return Err("骨根墓地行动响应外壳损坏".into());}}}}for e in &self.effects{match e{Effect::Frame{frame:f}if frame_related(f)=>return Err("骨根单步不能保留游离续体".into()),Effect::Declare{declaration:d}if related(&d.ability)||d.source.card.definition==ID=>{if d.ability.key!=PREPARE{return Err("骨根没有其他触发声明".into());}self.jc035_declaration(d)?;},_=>()}}if let Some(p)=&self.pending{if let ChoiceResolution::Frame{frame:f,choice}=&p.resolution{if frame_related(f)||matches!(choice,FrameChoice::CQ27Bottom){if !matches!(choice,FrameChoice::CQ27Bottom)||!ids.insert(&f.frame_id){return Err("骨根待选或同帧载体不符".into());}self.validate_cq27_pending(p,f)?;}}}Ok(())}
}
